<script setup lang="ts">
import { computed, nextTick, onMounted, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import MarkdownIt from 'markdown-it'
import type { EChartsInstance, EChartsOption } from '../utils/echarts'
import { ArrowLeft, ArrowRight, ArrowUpRight, BookOpen, Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Clock3, Download, FileText, Filter, Flame, FolderOpen, Info, Lightbulb, ListFilter, Maximize2, MessageSquare, MoreHorizontal, Network, Plus, RotateCcw, Search, Send, Settings2, Sparkles, Star, Target, ThumbsDown, ThumbsUp, Trash2, Upload, X, ZoomIn, ZoomOut, Copy as CopyIcon, Bell as BellIcon, LockKeyhole as LockIcon } from 'lucide-vue-next'
import ChartPanel from '../components/ChartPanel.vue'
import { studyApi } from '../api'
import { useStudyStore } from '../stores/study'
import { profileState, saveProfile, type StudyProfile } from '../stores/profile'
import { preferences, savePreferences } from '../stores/preferences'
import type { Course, KnowledgeNode, Question, Material } from '../types'
import '../styles/learning-loop.css'

type Source = { document: string; section: string; excerpt: string; score: string }
type Message = { role: 'user'|'assistant'; text: string; sources?: Source[]; loading?: boolean; feedback?: string }
const route = useRoute(); const router = useRouter(); const store = useStudyStore(); const md = new MarkdownIt({ html: false, linkify: true, breaks: true })
const section = computed(() => String(route.meta.section || '')); const pageTitle = computed(() => String(route.meta.title || '学习空间'))
const q = ref(''); const selectedCourse = ref('全部课程'); const courseCategoryFilter=ref('全部课程'); const drawer = ref(false); const toast = ref(''); let toastTimer: number | undefined
function notify(message: string) { toast.value=message; window.clearTimeout(toastTimer); toastTimer=window.setTimeout(()=>toast.value='',2600) }
function markdown(text:string) { return md.render(text) }

// Learning graph: force layout, search, category toggles and node inspector.
const graphHost = ref<HTMLElement>(); const graphFull = ref(false); const graphNodes = ref<KnowledgeNode[]>([]); const graphLinks = ref<Array<{source:string;target:string}>>([]); const courses = ref<Course[]>([]); const graphCourseId = ref(String(route.query.course || '')); const graphCourseName = computed(()=>courses.value.find(course=>course.id===graphCourseId.value)?.name||'当前课程'); const selectedNode = ref<KnowledgeNode>({id:'',name:'',type:'concept',mastery:0,description:''}); const selectedTypes = ref(['course','chapter','concept','application']); let graphChart: EChartsInstance | undefined; let graphObserver: ResizeObserver | undefined; let graphEcharts: typeof import('../utils/echarts') | undefined
const typeMeta: Record<string,{label:string;color:string}> = { course:{label:'课程',color:'#7054d9'}, chapter:{label:'章节',color:'#54b7a3'}, concept:{label:'知识点',color:'#8e80e8'}, application:{label:'综合应用',color:'#e9a45a'} }
const graphTextCanvas = document.createElement('canvas')
const graphTextContext = graphTextCanvas.getContext('2d')
function graphNodeSize(node: KnowledgeNode, compact: boolean, fontSize: number) {
  const baseSize = compact
    ? node.id === graphCourseId.value ? 56 : node.type === 'chapter' ? 44 : node.type === 'application' ? 34 : 30
    : node.id === graphCourseId.value ? 76 : node.type === 'chapter' ? 55 : node.type === 'application' ? 37 : 34
  if (!graphTextContext) return baseSize

  const fontWeight = node.id === graphCourseId.value ? 700 : 600
  graphTextContext.font = `${fontWeight} ${fontSize}px sans-serif`
  const textWidth = graphTextContext.measureText(node.name).width
  // Leave room for the node border and a little breathing space around the label.
  return Math.max(baseSize, Math.ceil(textWidth + 16))
}
function graphOption(): EChartsOption { const compact=window.innerWidth<=680; const visibles=graphNodes.value.filter(n=>selectedTypes.value.includes(n.type)); const ids=new Set(visibles.map(n=>n.id)); return { animationDuration:500, tooltip:{trigger:'item',formatter:(p:any)=>p.data?.name||''}, legend:{show:false}, series:[{type:'graph',layout:'force',roam:true,draggable:true,scaleLimit:{min:.55,max:2.8},force:{repulsion:compact?75:260,edgeLength:compact?[38,72]:[58,140],gravity:.08},data:visibles.map(n=>{const fontSize=compact?(n.id===graphCourseId.value?12:9):(n.id===graphCourseId.value?14:11);return {id:n.id,name:n.name,symbolSize:graphNodeSize(n,compact,fontSize),itemStyle:{color:typeMeta[n.type].color,borderColor:'#fff',borderWidth:n.id===graphCourseId.value?5:3,shadowBlur:n.id===graphCourseId.value?28:12,shadowColor:n.id===graphCourseId.value?'rgba(112,84,217,.32)':'rgba(89,76,140,.15)'},label:{show:true,color:'#fff',fontWeight:n.id===graphCourseId.value?700:600,fontSize},emphasis:{scale:1.2,itemStyle:{borderColor:'#fff',borderWidth:4}}}}),links:graphLinks.value.filter(l=>ids.has(l.source)&&ids.has(l.target)).map(l=>({...l, symbol:['none','arrow'],symbolSize:7,lineStyle:{color:'#c8c2dc',width:1.5,curveness:.06}})),edgeSymbol:['none','arrow'],edgeSymbolSize:6,emphasis:{focus:'adjacency',lineStyle:{width:3,color:'#8c75dc'}},selectedMode:'single'}] } }
async function loadGraph(courseId=graphCourseId.value) { if(!courseId){graphNodes.value=[];graphLinks.value=[];return} graphCourseId.value=courseId; const graph=await studyApi.graph(courseId); graphNodes.value=graph.nodes; graphLinks.value=graph.links; selectedNode.value=graph.nodes.find((node:KnowledgeNode)=>node.id===String(route.query.node||''))||graph.nodes[0]||{id:'',name:'',type:'concept',mastery:0,description:''}; if(section.value==='graph'){await nextTick();await drawGraph()} }
async function drawGraph() { if(!graphHost.value)return; graphEcharts ||= await import('../utils/echarts'); if(!graphHost.value||section.value!=='graph')return; if(!graphChart) graphChart=graphEcharts.echarts.init(graphHost.value); const instance=graphChart; instance.setOption(graphOption(),true); instance.off('click'); instance.on('click',(p:any)=>{if(p.dataType==='node'){const item=graphNodes.value.find(n=>n.id===p.data.id);if(item){selectedNode.value=item;drawer.value=true}}}); graphObserver?.disconnect();graphObserver=new ResizeObserver(()=>graphChart?.resize());graphObserver.observe(graphHost.value) }
function focusNode(id:string) { const n=graphNodes.value.find(x=>x.id===id);if(n){selectedNode.value=n;drawer.value=true;graphChart?.dispatchAction({type:'focusNodeAdjacency',seriesIndex:0,dataIndex:graphNodes.value.filter(x=>selectedTypes.value.includes(x.type)).findIndex(x=>x.id===id)});graphChart?.dispatchAction({type:'highlight',seriesIndex:0,dataIndex:graphNodes.value.filter(x=>selectedTypes.value.includes(x.type)).findIndex(x=>x.id===id)})} }
function zoomGraph(delta:number){graphChart?.dispatchAction({type:delta>0?'dataZoom':'dataZoom',delta})}
watch([selectedTypes,section,graphFull],async()=>{if(section.value==='graph'){await nextTick();drawGraph()}},{deep:true})
watch(section,async(nextSection)=>{try{if(nextSection==='graph')await loadGraph(String(route.query.course||graphCourseId.value));if(nextSection==='path')await loadPersonalizedPath(String(route.query.course||graphCourseId.value));if(nextSection==='quiz'&&(localStorage.getItem('studypath.reviewQuestionId')||localStorage.getItem('studypath.quizConceptId')))await beginQuiz()}catch(error){notify(error instanceof Error?error.message:'学习内容加载失败')}})
watch(()=>route.query.course,async(value)=>{if(typeof value!=='string'||!value)return;graphCourseId.value=value;try{if(section.value==='graph')await loadGraph(value);if(section.value==='path')await loadPersonalizedPath(value)}catch(error){notify(error instanceof Error?error.message:'课程数据加载失败')}})
onMounted(async()=>{await store.loadTasks();try{courses.value=await studyApi.courses();if(!quizCourseId.value&&courses.value.length)quizCourseId.value=courses.value[0].id;if(!graphCourseId.value&&courses.value.length)graphCourseId.value=courses.value[0].id;quizTopic.value=courses.value.find(course=>course.id===quizCourseId.value)?.name||'';mistakeList.value=await studyApi.mistakes();if(!mistakeList.value.length){try{const legacy=JSON.parse(localStorage.getItem('studypath.learning-loop.mistakes')||'[]') as MistakeRecord[];if(legacy.length){mistakeList.value=await studyApi.saveMistakes(legacy.map(item=>({question_id:item.questionId,payload:item as unknown as Record<string,unknown>})));localStorage.removeItem('studypath.learning-loop.mistakes')}}catch{}}quizHistory.value=await studyApi.quizAttempts();studyAnalytics.value=await studyApi.analytics(30)}catch(error){notify(error instanceof Error?error.message:'学习数据加载失败')}if(section.value==='graph')await loadGraph(String(route.query.course||graphCourseId.value));if(section.value==='path')await loadPersonalizedPath(String(route.query.course||graphCourseId.value));if(section.value==='quiz')await loadGraph(quizCourseId.value);if(section.value==='quiz'&&(localStorage.getItem('studypath.reviewQuestionId')||localStorage.getItem('studypath.quizConceptId')))await beginQuiz() })
onBeforeUnmount(()=>{graphObserver?.disconnect();graphChart?.dispose();window.clearTimeout(toastTimer)})
const prerequisites = computed(()=>graphLinks.value.filter(edge=>edge.target===selectedNode.value.id).map(edge=>edge.source))
const related = computed(()=>graphLinks.value.filter(l=>l.source===selectedNode.value.id||l.target===selectedNode.value.id).map(l=>graphNodes.value.find(n=>n.id===(l.source===selectedNode.value.id?l.target:l.source))).filter(Boolean))

// AI Q&A and evidence drawer. The mock label travels with each response.
const chats=ref([{id:1,title:'进程与线程有什么区别？',course:'操作系统',time:'今天 10:42'},{id:2,title:'二叉搜索树的删除操作',course:'数据结构',time:'昨天 20:18'},{id:3,title:'TCP 拥塞窗口如何变化',course:'计算机网络',time:'周一 16:30'}]); const activeChat=ref(1); const messages=ref<Message[]>([]); const chatInput=ref(''); const chatBusy=ref(false); const chatScroll=ref<HTMLElement>(); const sourceSelected=ref<Source|null>(null); const sourcesOpen=ref(true)
const promptExamples=['解释操作系统中的进程与线程','二叉搜索树与平衡二叉树的区别','TCP 三次握手为什么不能改为两次','动态规划和贪心算法如何选择']
watch(activeChat,()=>{messages.value=[]})
async function sendQuestion(value: string | Event = chatInput.value){const text=(typeof value==='string'?value:chatInput.value).trim();if(!text||chatBusy.value)return;messages.value.push({role:'user',text});chatInput.value='';chatBusy.value=true;messages.value.push({role:'assistant',text:'',loading:true});await nextTick();chatScroll.value?.scrollTo({top:chatScroll.value.scrollHeight,behavior:'smooth'});const result=await studyApi.ask(text);messages.value[messages.value.length-1]={role:'assistant',text:result.answer,sources:result.sources};chatBusy.value=false;await nextTick();chatScroll.value?.scrollTo({top:chatScroll.value.scrollHeight,behavior:'smooth'})}
async function copyAnswer(text:string){await navigator.clipboard?.writeText(text);notify('回答已复制')}
function newChat(){activeChat.value=Date.now();chats.value.unshift({id:activeChat.value,title:'新建学习对话',course:selectedCourse.value==='全部课程'?'未选择课程':selectedCourse.value,time:'刚刚'});messages.value=[]}

// Library uploads, validation, local demonstration only.
const statusFilter=ref('全部状态'); const materials=ref<Material[]>(JSON.parse(localStorage.getItem('studypath.materials')||'null')||[{id:1,name:'数据结构课程讲义.pdf',type:'PDF',size:'8.4 MB',status:'已索引',course:'数据结构',date:'2026/10/16'},{id:2,name:'操作系统复习提纲.docx',type:'DOCX',size:'1.2 MB',status:'已索引',course:'操作系统',date:'2026/10/14'},{id:3,name:'TCP 拥塞控制学习笔记.md',type:'MD',size:'18 KB',status:'处理中',course:'计算机网络',date:'2026/10/17'},{id:4,name:'算法设计课堂记录.txt',type:'TXT',size:'42 KB',status:'待处理',course:'数据结构',date:'2026/10/18'}] as Material[]); const fileInput=ref<HTMLInputElement>(); const materialDetail=ref<Material|null>(null)
const visibleMaterials=computed(()=>materials.value.filter(m=>m.name.toLowerCase().includes(q.value.toLowerCase())&&(selectedCourse.value==='全部课程'||m.course===selectedCourse.value)&&(statusFilter.value==='全部状态'||m.status===statusFilter.value)))
function saveMaterials(){localStorage.setItem('studypath.materials',JSON.stringify(materials.value))}
function uploadFiles(files:FileList|null){if(!files)return;for(const file of Array.from(files)){const ext=file.name.split('.').pop()?.toLowerCase()||'';if(!['pdf','docx','txt','md'].includes(ext)){notify(`${file.name}：仅支持 PDF、DOCX、TXT、Markdown`);continue}if(file.size>20*1024*1024){notify(`${file.name}：文件需小于 20 MB`);continue}const item:Material={id:Date.now()+Math.random(),name:file.name,type:ext.toUpperCase(),size:file.size>1024*1024?`${(file.size/1024/1024).toFixed(1)} MB`:`${Math.max(1,Math.round(file.size/1024))} KB`,status:'待处理',course:selectedCourse.value==='全部课程'?'数据结构':selectedCourse.value,date:new Date().toLocaleDateString('zh-CN')};materials.value.unshift(item);saveMaterials();window.setTimeout(()=>{const current=materials.value.find(m=>m.id===item.id);if(current){current.status='失败';saveMaterials()}},2200);notify('已加入账户数据队列；尚未解析或写入向量数据库。')} }
function deleteMaterial(id:number){materials.value=materials.value.filter(m=>m.id!==id);saveMaterials();notify('资料已从本地列表移除')}

// Quiz evaluates only objective answers from the selected mock question set.
type LearningAttempt = { at: string; correct: boolean; selectedAnswer: string; feedback: string }
type MistakeRecord = { id: number; questionId: number; conceptId?: string; title: string; topic: string; course: string; wrong: number; difficulty: string; saved: boolean; misconception: string; lastWrongAt: string; nextReviewAt: string; correctStreak: number; lastCorrectAt: string | null; mastered: boolean; attempts: LearningAttempt[]; evidence?: Question['evidence'] }
const mistakeList=ref<MistakeRecord[]>([])
const studyAnalytics=ref<{days:Array<{date:string;seconds:number;hours:number}>;totalSeconds:number;totalHours:number}>({days:[],totalSeconds:0,totalHours:0})
const quizQuestions=ref<Question[]>([]); const quizStarted=ref(false); const quizAnswers=ref<Record<number,string|string[]>>({}); const quizSubmitted=ref(false); const currentQuestion=ref(0); const quizCount=ref('3'); const quizCourseId=ref(String(route.query.course||'')); const quizTopic=ref(''); const reviewMode=ref(false)
const reviewQuestionId=ref<number|null>(null); const quizStartedAt=ref(0)
const score=computed(()=>{const objective=quizQuestions.value.filter(x=>x.type!=='简答题');const correct=objective.filter(x=>{const a=quizAnswers.value[x.id];return Array.isArray(x.answer)?Array.isArray(a)&&x.answer.length===a.length&&x.answer.every(v=>a.includes(v)):a===x.answer}).length;return Math.round(correct/Math.max(1,objective.length)*100)})
function saveMistakes(){return studyApi.saveMistakes(mistakeList.value.map(item=>({question_id:item.questionId,payload:item as unknown as Record<string,unknown>})))}
function scheduleIn(days:number){const date=new Date();date.setDate(date.getDate()+days);return date.toISOString()}
const dueMistakes=computed(()=>mistakeList.value.filter(item=>!item.mastered&&new Date(item.nextReviewAt)<=new Date()).length)
const adaptiveMistake=computed(()=>mistakeList.value.filter(item=>!item.mastered).sort((a,b)=>Number(new Date(a.nextReviewAt)>new Date())-Number(new Date(b.nextReviewAt)>new Date())||b.wrong-a.wrong)[0])
const weakMistakes=computed(()=>mistakeList.value.filter(item=>!item.mastered).sort((a,b)=>b.wrong-a.wrong).slice(0,3))
type LearningPathStep={nodeId:string;name:string;type:string;mastery:number;wrongCount:number;due:boolean;prerequisites:string[];state:'current'|'next';reason:string}
type PathViewStep=LearningPathStep&{id:string;tag:string;time:string;done:boolean}
const generatedPath=ref<LearningPathStep[]>([]);const pathProgress=ref(0);const pathLoading=ref(false);const pathError=ref('');const pathCustomized=ref(false);const pathDirty=ref(false)
async function loadPersonalizedPath(courseId=graphCourseId.value){if(!courseId){generatedPath.value=[];pathProgress.value=0;pathError.value='当前账号没有可用课程';return}graphCourseId.value=courseId;pathLoading.value=true;pathError.value='';try{const result=await studyApi.learningPath(courseId);generatedPath.value=result.steps;pathProgress.value=result.progress;pathCustomized.value=Boolean(result.customized);pathDirty.value=false}catch(error){pathError.value=error instanceof Error?error.message:'个性化学习路径加载失败';throw error}finally{pathLoading.value=false}}
const pathSteps=computed<PathViewStep[]>(()=>generatedPath.value.map((step,index)=>({ ...step,id:step.nodeId,tag:step.due?'到期复习':step.wrongCount?`错题 ${step.wrongCount} 次`:step.mastery<40?'重点巩固':'能力提升',time:`约 ${Math.max(15,preferences.dailyFocusHours*15)} 分钟`,done:step.mastery>=80,state:index===0?'current':'next' })))
function movePathStep(index:number,delta:number){const target=index+delta;if(target<0||target>=generatedPath.value.length)return;const reordered=[...generatedPath.value];const [step]=reordered.splice(index,1);reordered.splice(target,0,step);generatedPath.value=reordered;pathDirty.value=true}
async function savePathOrder(){try{await studyApi.saveLearningPath(graphCourseId.value,generatedPath.value.map(step=>step.nodeId));pathCustomized.value=true;pathDirty.value=false;notify('自定义学习顺序已保存到账户')}catch(error){notify(error instanceof Error?error.message:'学习路径保存失败')}}
async function resetPathOrder(){try{await studyApi.saveLearningPath(graphCourseId.value,[]);pathCustomized.value=false;pathDirty.value=false;await loadPersonalizedPath();notify('已恢复系统推荐顺序')}catch(error){notify(error instanceof Error?error.message:'恢复推荐顺序失败')}}
function rebuildPath(){void loadPersonalizedPath().then(()=>notify('已根据课程先修关系、掌握度和错题重新规划')).catch(error=>notify(error instanceof Error?error.message:'学习路径更新失败'))}
async function addPlanTask(title:string,course=selectedCourse.value==='全部课程'?(courses.value[0]?.name||'学习空间'):selectedCourse.value){try{await store.addTask(title,course,`${selectedPlanDay.value} · 09:00`);notify('学习任务已保存到账户')}catch(error){notify(error instanceof Error?error.message:'任务保存失败，请重试')}}
async function togglePlanTask(id:number){try{await store.toggleTask(id)}catch(error){notify(error instanceof Error?error.message:'任务状态保存失败，请重试')}}
async function addCurrentToPlan(){const step=pathSteps.value.find(item=>!item.done);if(!step)return;await addPlanTask(`学习「${step.name}」`,graphCourseName.value)}
async function startPathStep(step:LearningPathStep){localStorage.setItem('studypath.quizConceptId',step.nodeId);localStorage.setItem('studypath.quizCourseId',graphCourseId.value);await router.push({path:'/quiz',query:{course:graphCourseId.value}})}
async function beginConceptPractice(nodeId:string,courseId:string){localStorage.setItem('studypath.quizConceptId',nodeId);localStorage.setItem('studypath.quizCourseId',courseId);quizCourseId.value=courseId;await router.push({path:'/quiz',query:{course:courseId}})}
async function toggleCurrentMastery(){try{const mastery=selectedNode.value.mastery>=80?40:100;await studyApi.saveMastery(selectedNode.value.id,mastery);selectedNode.value.mastery=mastery;const node=graphNodes.value.find(item=>item.id===selectedNode.value.id);if(node)node.mastery=mastery;const learnable=graphNodes.value.filter(item=>item.type==='concept'||item.type==='application');const progress=Math.round(learnable.filter(item=>item.mastery>=80).length/Math.max(1,learnable.length)*100);await studyApi.saveCourseProgress(graphCourseId.value,progress,selectedNode.value.id);notify(mastery>=80?'已记录为掌握':'已更新掌握度')}catch(error){notify(error instanceof Error?error.message:'掌握度保存失败')}}
function diagnosisFor(question:Question){const answer=quizAnswers.value[question.id];if(answer===undefined||answer==='')return '未作答；建议先阅读知识卡，再尝试举一反三练习。';if(isCorrect(question))return '回答正确，继续通过间隔复测确认稳定掌握。';const choices=Array.isArray(answer)?answer:[answer];const distractor=choices.find(choice=>!(Array.isArray(question.answer)?question.answer.includes(choice):choice===question.answer));if(distractor)return question.misconceptions?.[distractor]||'所选答案与目标概念不符，先核对知识卡再做举一反三练习。';return '你选对了部分内容，但还遗漏了必要条件；对照正确选项和知识卡逐项检查。'}
const quizConceptFilter=ref('')
const quizConceptOptions=computed(()=>graphNodes.value.filter(node=>node.type==='concept'||node.type==='application'))
watch(quizCourseId,async(courseId)=>{quizConceptFilter.value='';if(courseId){graphCourseId.value=courseId;try{await loadGraph(courseId)}catch(error){notify(error instanceof Error?error.message:'课程知识点加载失败')}}})
async function beginQuiz(){
  let bank:Question[]
  try{bank=await studyApi.questions()}catch(error){notify(error instanceof Error?error.message:'题库加载失败');return}
  const requested=Number(localStorage.getItem('studypath.reviewQuestionId')||'')
  const conceptId=localStorage.getItem('studypath.quizConceptId')||quizConceptFilter.value
  const courseId=localStorage.getItem('studypath.quizCourseId')||String(route.query.course||quizCourseId.value)
  const hasReview=Number.isFinite(requested)&&requested>0
  let selected:Question[]=[]
  reviewMode.value=hasReview
  reviewQuestionId.value=hasReview?requested:null
  if(hasReview){
    const target=bank.find(question=>question.id===requested)
    const transfer=target?.transferQuestionIds?.map((id:number)=>bank.find(question=>question.id===id)).find(item=>item&&item.courseId===target.courseId)
    selected=[target,transfer].filter((item):item is Question=>Boolean(item))
    if(target){quizCourseId.value=target.courseId||courseId;quizTopic.value=target.course||quizTopic.value}
  }else if(conceptId){
    quizConceptFilter.value=conceptId
    selected=bank.filter(question=>question.conceptId===conceptId&&(!courseId||question.courseId===courseId)&&question.type!=='简答题').slice(0,Number(quizCount.value))
  }else{
    selected=bank.filter(question=>question.courseId===courseId&&question.type!=='简答题').slice(0,Number(quizCount.value))
  }
  localStorage.removeItem('studypath.reviewQuestionId')
  localStorage.removeItem('studypath.quizConceptId')
  localStorage.removeItem('studypath.quizCourseId')
  if(!selected.length){reviewMode.value=false;quizQuestions.value=[];notify('当前课程或知识点暂时没有可用客观题。请更换课程或联系管理员补充题目。');return}
  quizCourseId.value=selected[0].courseId||courseId||courses.value[0]?.id||''
  quizTopic.value=selected[0].course||courses.value.find(course=>course.id===selected[0].courseId)?.name||''
  quizQuestions.value=selected
  quizStarted.value=true;quizSubmitted.value=false;quizAnswers.value={};currentQuestion.value=0;quizStartedAt.value=Date.now()
}
function toggleAnswer(question:Question,option:string){if(question.type==='多选题'){const arr=Array.isArray(quizAnswers.value[question.id])?[...quizAnswers.value[question.id] as string[]]:[];quizAnswers.value[question.id]=arr.includes(option)?arr.filter(x=>x!==option):[...arr,option]}else quizAnswers.value[question.id]=option}
async function submitQuiz(){let stored:any;try{stored=await studyApi.saveQuizAttempt({course_id:quizQuestions.value[0]?.courseId||quizCourseId.value,question_ids:quizQuestions.value.map(item=>item.id),answers:Object.fromEntries(Object.entries(quizAnswers.value).map(([id,value])=>[id,value])),duration_seconds:Math.max(0,Math.round((Date.now()-quizStartedAt.value)/1000))});for(const result of stored.results||[]){const question=quizQuestions.value.find(item=>item.id===result.questionId);if(question){question.answer=result.answer;question.explanation=result.explanation;if(result.misconception&&typeof result.selectedAnswer==='string')question.misconceptions={[result.selectedAnswer]:result.misconception}}}quizHistory.value.unshift({...stored,course:quizQuestions.value[0]?.course||quizTopic.value});quizSubmitted.value=true}catch(error){notify(error instanceof Error?error.message:'测验记录保存失败');return}const now=new Date();const concepts=new Map<string,Question[]>();for(const question of quizQuestions.value){if(question.type==='简答题')continue;const key=question.conceptId||String(question.id);concepts.set(key,[...(concepts.get(key)||[]),question])}for(const group of concepts.values()){const question=group.find(item=>!isCorrect(item))||group[0];const prior=mistakeList.value.find(item=>item.questionId===question.id)||mistakeList.value.find(item=>group.some(candidate=>candidate.id===item.questionId));const selected=quizAnswers.value[question.id];const attempt:LearningAttempt={at:now.toISOString(),correct:isCorrect(question),selectedAnswer:Array.isArray(selected)?selected.join('、'):selected||'未作答',feedback:diagnosisFor(question)};if(reviewMode&&prior){const updated=await studyApi.reviewMistake(prior.questionId,{correct:attempt.correct,selected_answer:attempt.selectedAnswer,note:attempt.feedback});Object.assign(prior,updated);continue}if(!isCorrect(question)){if(prior){prior.wrong+=1;prior.correctStreak=0;prior.mastered=false;prior.misconception=attempt.feedback;prior.lastWrongAt=now.toISOString();prior.nextReviewAt=scheduleIn(1);prior.evidence=question.evidence||prior.evidence;prior.attempts.push(attempt)}else{mistakeList.value.unshift({id:question.id,questionId:question.id,conceptId:question.conceptId,title:question.title,topic:question.topic,course:question.course||courses.value.find(course=>course.id===question.courseId)?.name||'学习空间',wrong:1,difficulty:question.difficulty,saved:false,misconception:attempt.feedback,lastWrongAt:now.toISOString(),nextReviewAt:scheduleIn(1),correctStreak:0,lastCorrectAt:null,mastered:false,attempts:[attempt],evidence:question.evidence})}}else if(prior&&!prior.mastered){prior.attempts.push(attempt);const last=prior.lastCorrectAt?new Date(prior.lastCorrectAt):null;const separated=Boolean(last&&now.getTime()-last.getTime()>=24*60*60*1000);if(separated){prior.correctStreak+=1;prior.lastCorrectAt=now.toISOString();if(prior.correctStreak>=2){prior.mastered=true;prior.nextReviewAt=''}else prior.nextReviewAt=scheduleIn(3)}else{prior.lastCorrectAt=now.toISOString();prior.correctStreak=Math.max(1,prior.correctStreak);prior.nextReviewAt=scheduleIn(1)}}}await saveMistakes();notify('测验与错题记录已保存到账户')}
const selectedAnswer=(question:Question,option:string)=>Array.isArray(quizAnswers.value[question.id])?quizAnswers.value[question.id].includes(option):quizAnswers.value[question.id]===option
function isCorrect(question:Question){const answer=quizAnswers.value[question.id];return Array.isArray(question.answer)?Array.isArray(answer)&&question.answer.length===answer.length&&question.answer.every(x=>answer.includes(x)):answer===question.answer}

const filteredCourses=computed(()=>courses.value.filter(c=>c.name.toLowerCase().includes(q.value.toLowerCase())&&(courseCategoryFilter.value==='全部课程'||c.category===courseCategoryFilter.value)))
const courseDetail=ref<string|null>(null)
const courseDetailNodes=ref<KnowledgeNode[]>([]);const courseDetailLoading=ref(false);const courseDetailError=ref('')
const courseCategories=computed(()=>Array.from(new Set(courses.value.map(course=>course.category).filter(Boolean))))
async function openCourse(courseId:string){courseDetail.value=courseId;courseDetailNodes.value=[];courseDetailError.value='';courseDetailLoading.value=true;try{const graph=await studyApi.graph(courseId);courseDetailNodes.value=graph.nodes}catch(error){courseDetailError.value=error instanceof Error?error.message:'课程目录读取失败'}finally{courseDetailLoading.value=false}}
function openCourseNode(courseId:string,nodeId:string){courseDetail.value=null;void router.push({path:'/graph',query:{course:courseId,node:nodeId}})}
function viewCourseGraph(courseId:string){courseDetail.value=null;void router.push({path:'/graph',query:{course:courseId}})}
const mistakeDifficulty=ref('全部难度'); const sortMistakesDescending=ref(true)
const visibleMistakes=computed(()=>mistakeList.value.filter(item=>!item.mastered&&(selectedCourse.value==='全部课程'||item.course===selectedCourse.value)&&(mistakeDifficulty.value==='全部难度'||item.difficulty===mistakeDifficulty.value)).sort((a,b)=>sortMistakesDescending.value?b.wrong-a.wrong:a.wrong-b.wrong))
function openMistakePractice(questionId:number){void router.push(`/mistake-practice/${questionId}`)}
async function toggleMistakeSaved(item:MistakeRecord){const next=!item.saved;try{await studyApi.updateMistake(item.questionId,{saved:next});item.saved=next}catch(error){notify(error instanceof Error?error.message:'收藏状态保存失败')}}
const goal=ref(preferences.weeklyGoalHours); const daily=ref(preferences.dailyFocusHours); const notifications=ref(preferences.learningReminders); const displayName=computed(()=>profileState.name); const profileDraft=reactive<StudyProfile>({...profileState})
const learningSubjectsText=computed({get:()=>profileDraft.learningSubjects.join('、'),set:(value:string)=>{profileDraft.learningSubjects=value.split(/[、，,]/).map(item=>item.trim()).filter(Boolean)}})
watch([goal,daily,notifications],([weekly,duration,reminders])=>{preferences.weeklyGoalHours=weekly;preferences.dailyFocusHours=duration;preferences.learningReminders=reminders;savePreferences()})
async function saveProfileChanges(){if(!profileDraft.name.trim()){notify('姓名不能为空');return}try{await saveProfile(profileDraft);notify('个人资料已保存到账户')}catch(error){notify(error instanceof Error?error.message:'资料保存失败')}}
type QuizRecord={at:string;score:number;questionCount:number;course:string}
const quizHistory=ref<QuizRecord[]>([])
const analyticsRange=ref(7)
const rangeRecords=computed(()=>quizHistory.value.filter(record=>Date.now()-new Date(record.at).getTime()<analyticsRange.value*86400000))
const averageScore=computed(()=>rangeRecords.value.length?Math.round(rangeRecords.value.reduce((sum,item)=>sum+item.score,0)/rangeRecords.value.length):null)
const analyticsPeriod=computed(()=>{const end=new Date();const start=new Date();start.setDate(end.getDate()-analyticsRange.value+1);return `${start.toLocaleDateString('zh-CN',{month:'long',day:'numeric',timeZone:'Asia/Shanghai'})} — ${end.toLocaleDateString('zh-CN',{month:'long',day:'numeric',timeZone:'Asia/Shanghai'})}`})
const trendOption=computed(()=>{const days=Array.from({length:analyticsRange.value},(_,index)=>{const date=new Date();date.setHours(0,0,0,0);date.setDate(date.getDate()-(analyticsRange.value-1-index));return date});const labels=days.map(date=>`${date.getMonth()+1}/${date.getDate()}`);const values=days.map(date=>{const key=date.toDateString();const attempts=rangeRecords.value.filter(item=>new Date(item.at).toDateString()===key);return attempts.length?Math.round(attempts.reduce((sum,item)=>sum+item.score,0)/attempts.length):null});return {tooltip:{trigger:'axis'},grid:{left:8,right:16,top:16,bottom:24,containLabel:true},xAxis:{type:'category',boundaryGap:false,data:labels,axisLine:{show:false},axisTick:{show:false},axisLabel:{color:'#8b8998'}},yAxis:{type:'value',min:0,max:100,splitLine:{lineStyle:{color:'#efedf3',type:'dashed'}},axisLabel:{color:'#aaa8b5',formatter:'{value}%'}},series:[{type:'line',smooth:true,data:values,lineStyle:{color:'#7958df',width:3},areaStyle:{color:'rgba(121,88,223,.12)'},symbolSize:7,itemStyle:{color:'#7958df'}}]} as EChartsOption})
const distributionOption=computed(()=>({tooltip:{trigger:'item'},legend:{bottom:0,textStyle:{color:'#777486'}},series:[{type:'pie',radius:['48%','72%'],data:[{name:'已掌握错题',value:mistakeList.value.filter(item=>item.mastered).length,itemStyle:{color:'#7958df'}},{name:'待复测错题',value:mistakeList.value.filter(item=>!item.mastered&&new Date(item.nextReviewAt)>new Date()).length,itemStyle:{color:'#b7a7ed'}},{name:'已到期错题',value:dueMistakes.value,itemStyle:{color:'#e8e5ef'}}],label:{show:false}}]} as EChartsOption))
const todayTasks=computed(()=>store.tasks.filter(task=>taskDate(task.date)===selectedPlanDay.value))
const nextPlanDay=computed(()=>{const date=new Date(`${selectedPlanDay.value}T12:00:00`);date.setDate(date.getDate()+1);return date.toISOString().slice(0,10)})
const nextDayTasks=computed(()=>store.tasks.filter(task=>taskDate(task.date)===nextPlanDay.value))
const calendarDays=computed(()=>Array.from({length:7},(_,index)=>{const date=new Date(`${selectedPlanDay.value}T12:00:00`);date.setDate(date.getDate()+index);const value=date.toISOString().slice(0,10);return {value,label:new Intl.DateTimeFormat('zh-CN',{weekday:'short',day:'numeric'}).format(date),count:store.tasks.filter(task=>taskDate(task.date)===value).length}}))
const selectedPlanDay=ref(new Date().toISOString().slice(0,10)); const planView=ref<'list'|'calendar'>('list')
const planDate=computed(()=>new Intl.DateTimeFormat('zh-CN',{year:'numeric',month:'long',day:'numeric',weekday:'long',timeZone:'Asia/Shanghai'}).format(new Date(`${selectedPlanDay.value}T12:00:00`)))
const tomorrowDate=computed(()=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'short',timeZone:'Asia/Shanghai'}).format(new Date(Date.now()+86400000)))
function taskDate(value:string){if(value.includes('明天'))return new Date(Date.now()+86400000).toLocaleDateString('sv-SE');if(value.includes('今天'))return new Date().toLocaleDateString('sv-SE');const prefix=value.match(/^\d{4}-\d{2}-\d{2}/)?.[0];if(prefix)return prefix;const parsed=new Date(value);return Number.isNaN(parsed.getTime())?new Date().toLocaleDateString('sv-SE'):parsed.toLocaleDateString('sv-SE')}
function shiftPlanDate(days:number){const date=new Date(`${selectedPlanDay.value}T12:00:00`);date.setDate(date.getDate()+days);selectedPlanDay.value=date.toISOString().slice(0,10)}
function goToday(){selectedPlanDay.value=new Date().toISOString().slice(0,10)}
function scrollSettings(id:string){document.getElementById(id)?.scrollIntoView({behavior:'smooth',block:'start'})}
function exportAnalytics(){const payload={generatedAt:new Date().toISOString(),rangeDays:analyticsRange.value,quizAttempts:rangeRecords.value,tasks:store.tasks,mistakes:mistakeList.value};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`studypath-report-${selectedPlanDay.value}.json`;link.click();URL.revokeObjectURL(url)}
async function editTask(task: {id:number;title:string}){const title=window.prompt('编辑学习任务',task.title);if(title?.trim()){const current=store.tasks.find(item=>item.id===task.id);if(current){const previous=current.title;current.title=title.trim();try{await store.persist();notify('任务已保存到账户')}catch(error){current.title=previous;notify(error instanceof Error?error.message:'任务保存失败，请重试')}}}}
</script>

<template>
  <div class="page-content workspace-page">
    <section class="page-intro"><div><div class="page-context"><span class="context-dot"></span>智学研途 <span>/</span> {{ pageTitle }}</div><h1>{{ section==='graph'?'课程知识图谱':section==='path'?'你的专属学习路径':section==='chat'?'AI 智能答疑':section==='analytics'?'学习数据分析':pageTitle }}</h1><p>{{ section==='path'?'根据当前课程图谱、个人掌握度与错题复习状态生成学习顺序。':section==='graph'?'查看课程知识点与先修关系；节点不代表个人掌握程度。':section==='chat'?'结合课程资料与可追溯证据，让每个问题都有依据。':section==='library'?'集中整理课程资料，为检索问答与复习建立知识底座。':section==='quiz'?'用一组短测验检验理解，把薄弱知识点及时找出来。':section==='courses'?'课程进度与知识点目录来自当前账号和课程图谱。':'把学习记录转化为清晰的下一步。' }}</p></div><div class="intro-actions"><span v-if="section==='chat'||section==='library'" class="demo-tag"><Sparkles :size="12" /> 本地演示</span><button v-if="section==='chat'" class="btn btn-primary" @click="newChat"><Plus :size="15" />新建对话</button><button v-if="section==='path'" class="btn btn-primary" @click="rebuildPath"><RotateCcw :size="15" />重新生成路径</button><button v-if="section==='path'" class="btn btn-secondary" @click="addCurrentToPlan"><Plus :size="15" />加入学习计划</button><button v-if="section==='quiz'&&!quizStarted" class="btn btn-primary" @click="beginQuiz"><Sparkles :size="15" />开始测验</button><button v-if="section==='library'" class="btn btn-primary" @click="fileInput?.click()"><Upload :size="15" />上传资料</button><input ref="fileInput" type="file" hidden multiple accept=".pdf,.docx,.txt,.md" @change="uploadFiles(($event.target as HTMLInputElement).files)" /></div></section>

    <!-- AI learning chat -->
    <section v-if="section==='chat'" class="chat-layout panel">
      <aside class="chat-sidebar"><div class="chat-side-header"><div class="chat-side-title">对话记录 <span>{{ chats.length }}</span></div><button class="icon-button" title="新建对话" @click="newChat"><Plus :size="16" /></button></div><label class="field-search"><Search :size="15" /><input v-model="q" placeholder="搜索历史对话" /></label><select v-model="selectedCourse" class="chat-course-select"><option>全部课程</option><option v-for="c in courses" :key="c.id">{{ c.name }}</option></select><div class="chat-history-label">最近对话</div><div class="chat-history-list"><button v-for="chat in chats.filter(x=>x.title.includes(q))" :key="chat.id" class="chat-history-item" :class="{current:activeChat===chat.id}" @click="activeChat=chat.id"><MessageSquare :size="15" /><span><b>{{ chat.title }}</b><small>{{ chat.course }} · {{ chat.time }}</small></span><MoreHorizontal :size="15" /></button><div v-if="!chats.filter(x=>x.title.includes(q)).length" class="empty-small">没有找到相关对话</div></div><div class="chat-side-foot"><span class="chat-status"><i></i>演示问答已就绪</span><small>回答基于本地 Mock 数据</small></div></aside>
      <div class="chat-main">
        <div v-if="messages.length" ref="chatScroll" class="chat-thread">
          <div class="thread-date">今天 · {{ chats.find(x => x.id === activeChat)?.course || '课程问答' }}</div>
          <article v-for="(message, i) in messages" :key="i" class="message" :class="message.role">
            <div v-if="message.role === 'assistant'" class="assistant-avatar"><Sparkles :size="15" /></div>
            <div class="message-body">
              <div class="message-author">{{ message.role === 'user' ? '我' : '智学研途学习助手' }} <span v-if="message.role === 'assistant'" class="mock-label">MOCK</span></div>
              <div v-if="message.loading" class="typing"><i></i><i></i><i></i><span>正在整理课程资料与答案…</span></div>
              <div v-else class="markdown-body" v-html="markdown(message.text)"></div>
              <div v-if="message.role === 'assistant' && !message.loading" class="message-tools">
                <button @click="copyAnswer(message.text)"><CopyIcon :size="13" />复制</button>
                <button :class="{positive: message.feedback === 'up'}" @click="message.feedback = message.feedback === 'up' ? '' : 'up'; notify('感谢你的反馈')"><ThumbsUp :size="13" />有帮助</button>
                <button :class="{positive: message.feedback === 'down'}" @click="message.feedback = message.feedback === 'down' ? '' : 'down'; notify('已记录反馈')"><ThumbsDown :size="13" />反馈</button>
              </div>
              <div v-if="message.sources?.length" class="evidence-box">
                <button class="evidence-toggle" @click="sourcesOpen = !sourcesOpen"><span><BookOpen :size="15" />参考来源 <b>{{ message.sources.length }}</b></span><ChevronDown :size="15" :class="{rotate: !sourcesOpen}" /></button>
                <div v-if="sourcesOpen" class="source-list">
                  <button v-for="source in message.sources" :key="source.document" class="source-card" @click="sourceSelected = source">
                    <span class="source-file"><FileText :size="15" /></span>
                    <span class="source-copy"><b>{{ source.document }}</b><small>{{ source.section }}</small><span>“{{ source.excerpt }}”</span><em><Check :size="11" /> {{ source.score }} · 本地模拟匹配</em></span>
                    <ArrowUpRight :size="14" />
                  </button>
                </div>
                <small class="evidence-note"><Info :size="12" />匹配分数为演示数据，非真实检索结果。</small>
              </div>
              <div v-else-if="message.role === 'assistant' && !message.loading" class="no-evidence"><Info :size="14" />未检索到足够可靠的课程资料，回答仅供参考。</div>
            </div>
          </article>
          <div v-if="!chatBusy" class="followup-row"><span>你还可以问</span><button @click="sendQuestion('能举一个具体的例子吗？')">能举个例子吗？ <ArrowUpRight :size="12" /></button><button @click="sendQuestion('请用更简单的话解释一遍')">换个方式解释 <ArrowUpRight :size="12" /></button></div>
        </div>
        <div v-else class="chat-welcome">
          <div class="welcome-spark"><Sparkles :size="20" /></div>
          <h2>你好，{{ displayName }}<br /><span>让我们一起把问题弄明白。</span></h2>
          <p>你好，我是智学研途学习助手。你可以向我提问课程概念、算法原理，或者上传学习资料后进行针对性问答。</p>
          <div class="chat-course-picker"><span>参考课程资料</span><select v-model="selectedCourse"><option>全部课程</option><option v-for="c in courses" :key="c.id">{{ c.name }}</option></select><span class="mock-label">本地 Mock</span></div>
          <div class="prompt-grid"><button v-for="(prompt, i) in promptExamples" :key="prompt" @click="sendQuestion(prompt)"><span class="prompt-number">0{{ i + 1 }}</span>{{ prompt }}<ArrowUpRight :size="14" /></button></div>
          <div class="mock-notice"><Info :size="14" />当前为本地演示回复，尚未连接真实大模型或向量检索服务。</div>
        </div>
        <div class="chat-composer">
          <div class="composer-tools"><button @click="notify('资料选择功能请前往学习资料库上传')"><Plus :size="15" />添加资料</button><span><i></i>{{ selectedCourse === '全部课程' ? '所有课程' : '检索 ' + selectedCourse }}</span></div>
          <div class="composer-input"><textarea v-model="chatInput" rows="2" placeholder="输入你的问题…（Enter 发送，Shift + Enter 换行）" @keydown.enter.exact.prevent="sendQuestion()"></textarea><button class="send-button" :disabled="!chatInput.trim() || chatBusy" aria-label="发送" @click="sendQuestion()"><Send :size="16" /></button></div>
          <div class="composer-foot"><span>AI 生成内容请结合课程资料核对</span><span>⌘ ↵ 发送</span></div>
        </div>
      </div>    </section>

    <!-- Interactive course graph -->
    <section v-else-if="section==='graph'" class="graph-page panel" :class="{'graph-full':graphFull}"><div class="graph-toolbar"><div class="graph-controls"><select v-model="graphCourseId" aria-label="选择课程" @change="loadGraph(graphCourseId)"><option v-for="course in courses" :key="course.id" :value="course.id">{{course.name}}</option></select><label class="field-search"><Search :size="14" /><input v-model="q" placeholder="搜索知识点" @keydown.enter="focusNode(graphNodes.find(x=>x.name.includes(q))?.id||graphCourseId)" /><button v-if="q" @click="focusNode(graphNodes.find(x=>x.name.includes(q))?.id||graphCourseId)"><ArrowRight :size="14" /></button></label><button class="btn btn-soft" @click="selectedTypes=['course','chapter','concept','application'];selectedNode=graphNodes[0];drawGraph()"><RotateCcw :size="14" />重置布局</button></div><div class="graph-actions"><button class="icon-button" title="全屏" @click="graphFull=!graphFull"><X v-if="graphFull" :size="17"/><Maximize2 v-else :size="17" /></button><button class="btn btn-primary btn-compact" @click="router.push('/path')"><Sparkles :size="14"/>生成学习路径</button></div></div><div class="graph-body"><div class="graph-legend-panel"><div class="graph-summary"><span>{{graphCourseName}}</span><strong>{{graphNodes.length}}</strong><small>个知识点</small></div><label class="field-search"><Search :size="14"/><input v-model="q" placeholder="查找知识点" /></label><div class="legend-title">节点类型</div><button v-for="(meta,type) in typeMeta" :key="type" class="legend-item" @click="selectedTypes.includes(type)?selectedTypes=selectedTypes.filter(x=>x!==type):selectedTypes.push(type);drawGraph()"><i :style="{background:meta.color}"/><span>{{ meta.label }}</span><Check v-if="selectedTypes.includes(type)" :size="14" /></button><div class="legend-divider"></div><div class="graph-data-note">节点与先修关系来自服务端课程目录；掌握度按当前账号记录显示。</div><div class="graph-hint"><Network :size="15"/><span>拖动节点调整布局<br/>滚轮缩放 · 点击查看详情</span></div></div><div class="graph-canvas"><div ref="graphHost" class="graph-echart"></div><div class="graph-canvas-caption"><span><i class="canvas-pulse"></i>当前展示 <b>{{graphNodes.filter(x=>selectedTypes.includes(x.type)).length}}</b> 个知识点</span><span>箭头表示知识依赖关系</span></div><div class="graph-zoom"><button title="缩小" @click="graphChart?.dispatchAction({type:'graphRoam',seriesIndex:0,zoom:0.85})"><ZoomOut :size="15"/></button><span>可拖动探索</span><button title="放大" @click="graphChart?.dispatchAction({type:'graphRoam',seriesIndex:0,zoom:1.15})"><ZoomIn :size="15"/></button></div></div></div><Transition name="drawer"><aside v-if="drawer" class="node-drawer"><div class="drawer-top"><span class="node-type-pill" :style="{'--node-color':typeMeta[selectedNode.type].color}"><i></i>{{ typeMeta[selectedNode.type].label }}</span><button class="icon-button" aria-label="关闭详情" @click="drawer=false"><X :size="17"/></button></div><div class="node-heading"><h2>{{selectedNode.name}}</h2><span>{{graphCourseName}} · {{selectedNode.type==='chapter'?'章节':'知识点'}}</span></div><div class="mastery-editor"><span>个人掌握度 <b>{{selectedNode.mastery}}%</b></span><button class="btn btn-soft" @click="toggleCurrentMastery">{{selectedNode.mastery>=80?'调整为待巩固':'标记已掌握'}}</button></div><div class="drawer-section"><h4>知识点解释</h4><p>{{selectedNode.description}}</p></div><div class="drawer-section"><h4>前置知识 <span>{{prerequisites.length}}</span></h4><div class="chip-list"><button v-for="id in prerequisites" :key="id" @click="focusNode(id)">{{graphNodes.find(x=>x.id===id)?.name}} <ArrowUpRight :size="11"/></button><small v-if="!prerequisites.length">这是当前课程的根节点</small></div></div><div class="drawer-section"><h4>相关知识点 <span>{{related.length}}</span></h4><div class="related-list"><button v-for="item in related.slice(0,4)" :key="item?.id" @click="item&&focusNode(item.id)"><span class="related-dot" :style="{background:typeMeta[item?.type||'concept'].color}"/>{{item?.name}}<ArrowRight :size="13"/></button></div></div><div class="drawer-section"><h4>学习资料</h4><p>资料上传并完成索引后，真实来源会显示在 AI 答疑引用中。</p><button class="text-link" @click="router.push('/library')">前往资料库 <ArrowUpRight :size="13"/></button></div><div class="drawer-actions"><button class="btn btn-primary" @click="router.push('/chat');chatInput=`请讲解${selectedNode.name}`"><Sparkles :size="14"/>AI 讲解</button><button class="btn btn-secondary" @click="addCurrentToPlan"><Plus :size="14"/>加入计划</button><button class="btn btn-soft" @click="beginConceptPractice(selectedNode.id,graphCourseId)"><Target :size="14"/>练习</button></div></aside></Transition></section>

    <!-- Courses -->
    <template v-else-if="section==='courses'"><div class="content-toolbar"><label class="field-search wide"><Search :size="15"/><input v-model="q" placeholder="搜索课程名称" /></label><select v-model="courseCategoryFilter" class="filter-select"><option>全部课程</option><option v-for="category in courseCategories" :key="category">{{category}}</option></select><button class="btn btn-soft" @click="router.push('/admin/curriculum')"><Settings2 :size="14"/>课程内容维护</button></div><div class="course-grid"><article v-for="course in filteredCourses" :key="course.id" class="course-card panel"><div class="course-card-head"><span class="course-icon-large" :style="{'--course-color':course.color}">{{course.icon}}</span><button class="icon-button" title="课程选项" @click="openCourse(course.id)"><MoreHorizontal :size="17"/></button></div><span class="course-category">{{course.category}}</span><h3>{{course.name}}</h3><p>当前章节：{{course.chapter}}</p><div class="course-progress-label"><span>{{course.points}} 个目录知识点</span><b>已学 {{course.progress}}%</b></div><button class="course-continue" @click="openCourse(course.id)"><span>查看课程目录 <ArrowRight :size="14"/></span><small>个人进度 {{course.progress}}%</small></button></article><div v-if="!filteredCourses.length" class="empty-state panel"><BookOpen :size="22"/><b>没有找到这门课程</b><span>换个关键词试试</span></div></div><div v-if="courseDetail" class="overlay" @click.self="courseDetail=null"><div class="modal-card"><button class="icon-button modal-close" @click="courseDetail=null"><X :size="17"/></button><div class="modal-icon" :style="{'--course-color':courses.find(c=>c.id===courseDetail)?.color}">{{courses.find(c=>c.id===courseDetail)?.icon}}</div><h2>{{courses.find(c=>c.id===courseDetail)?.name}}</h2><p>{{courses.find(c=>c.id===courseDetail)?.points}} 个目录知识点 · 当前进度 {{courses.find(c=>c.id===courseDetail)?.progress||0}}%</p><h4>课程知识点</h4><div v-if="courseDetailLoading" class="empty-state">正在读取课程图谱…</div><div v-else-if="courseDetailError" class="empty-state" role="alert">{{courseDetailError}}</div><div v-else-if="!courseDetailNodes.length" class="empty-state">这门课程暂时没有知识点，请先在课程内容维护中添加。</div><button v-else v-for="(node,i) in courseDetailNodes" :key="node.id" class="chapter-row" @click="openCourseNode(courseDetail!,node.id)"><span class="chapter-index">{{String(i+1).padStart(2,'0')}}</span><span>{{node.name}}</span><span>{{node.type}} · 掌握 {{node.mastery}}%</span><ChevronRight :size="14"/></button><button class="btn btn-primary modal-primary" @click="courseDetail=null;viewCourseGraph(courseDetail!)">打开课程知识图谱 <ArrowRight :size="14"/></button></div></div></template>

    <!-- Materials library -->
    <template v-else-if="section==='library'"><div class="library-notice"><Info :size="16"/><span><b>本地演示模式：</b>上传文件仅进入浏览器演示队列，尚未真实解析内容或写入向量数据库。</span><button @click="notify('正式环境可对接 POST /materials/upload 接口')">API 接入说明 <ArrowUpRight :size="12"/></button></div><div class="library-stats"><div><span>全部资料</span><b>{{materials.length}}</b></div><div><span>已建立索引</span><b>{{materials.filter(m=>m.status==='已索引').length}}</b></div><div><span>待处理</span><b>{{materials.filter(m=>m.status==='待处理'||m.status==='处理中').length}}</b></div><div><span>资料空间</span><b>6.8 <small>GB / 10 GB</small></b></div></div><div class="panel library-panel"><div class="library-toolbar"><label class="field-search wide"><Search :size="15"/><input v-model="q" placeholder="搜索文件名" /></label><select v-model="selectedCourse" class="filter-select"><option>全部课程</option><option v-for="c in courses" :key="c.id">{{c.name}}</option></select><select v-model="statusFilter" class="filter-select"><option>全部状态</option><option>待处理</option><option>处理中</option><option>已索引</option><option>失败</option></select><button class="btn btn-secondary" @click="fileInput?.click()"><Upload :size="14"/>选择文件</button></div><div class="material-table"><div class="material-head"><span>文件名称</span><span>所属课程</span><span>文件大小</span><span>状态</span><span>更新时间</span><span></span></div><div v-for="mat in visibleMaterials" :key="mat.id" class="material-row"><span class="material-name"><i class="file-type" :class="'file-'+mat.type.toLowerCase()">{{mat.type==='DOCX'?'W':mat.type==='PDF'?'P':mat.type==='MD'?'M':'T'}}</i><button @click="materialDetail=mat">{{mat.name}}</button></span><span>{{mat.course}}</span><span>{{mat.size}}</span><span><i class="status-chip" :class="'status-'+mat.status">{{mat.status}}</i></span><span>{{mat.date}}</span><span class="material-actions"><button title="预览详情" @click="materialDetail=mat"><ArrowUpRight :size="14"/></button><button title="删除资料" @click="deleteMaterial(mat.id)"><Trash2 :size="14"/></button></span></div><div v-if="!visibleMaterials.length" class="empty-state"><FolderOpen :size="23"/><b>还没有匹配的资料</b><span>上传讲义或笔记，让课程知识更有迹可循。</span></div></div><div class="upload-drop" @click="fileInput?.click()" @dragover.prevent @drop.prevent="uploadFiles($event.dataTransfer?.files||null)"><span><Upload :size="18"/></span><b>拖放文件到此处，或 <u>浏览文件</u></b><small>PDF、DOCX、TXT、Markdown · 单个文件最大 20 MB</small></div></div><div v-if="materialDetail" class="overlay" @click.self="materialDetail=null"><div class="modal-card material-modal"><button class="icon-button modal-close" @click="materialDetail=null"><X :size="17"/></button><span class="file-type file-pdf large-file">{{materialDetail.type.slice(0,1)}}</span><h2>{{materialDetail.name}}</h2><p>{{materialDetail.size}} · {{materialDetail.course}} · {{materialDetail.date}}</p><div class="preview-placeholder"><FileText :size="38"/><b>资料预览</b><span>本地演示模式暂不解析文档正文。</span><small>上传接口对接后可展示原文与检索定位。</small></div><button class="btn btn-primary modal-primary" @click="materialDetail=null">完成</button></div></div></template>

    <!-- Personalized path -->
    <section v-else-if="section==='path'" class="path-layout"><div class="path-main panel"><div class="path-topline"><span><Sparkles :size="14"/> {{ graphCourseName }} · 个性化学习路径</span><div class="path-edit-actions"><button v-if="pathCustomized||pathDirty" class="btn btn-secondary" :disabled="pathLoading" @click="resetPathOrder">恢复推荐顺序</button><button v-if="pathDirty" class="btn btn-primary" @click="savePathOrder">保存自定义顺序</button><button class="btn btn-soft" :disabled="pathLoading" @click="rebuildPath"><RotateCcw :size="14"/>{{pathLoading?'正在规划':'重新规划'}}</button></div></div><div class="path-progress"><div><span>知识点掌握进度</span><b>{{pathProgress}}%</b></div><div class="progress-line"><i :style="{width:pathProgress+'%'}"/></div></div><div v-if="pathLoading" class="adaptive-review-empty">正在结合课程先修关系、个人掌握度与错题记录生成学习顺序…</div><div v-else-if="pathError" class="adaptive-review-empty" role="alert">{{pathError}} <button class="text-link" @click="rebuildPath">重试</button></div><div v-else-if="!pathSteps.length" class="adaptive-review-empty"><CheckCheck :size="16"/>这门课程的知识点已达到当前掌握标准，继续练习可以巩固长期记忆。</div><div v-else class="timeline"><div v-for="(step,i) in pathSteps" :key="step.nodeId" class="timeline-step" :class="'step-'+step.state"><div class="timeline-rail"><span class="timeline-node"><Check v-if="step.done" :size="13"/><span v-else>{{String(i+1).padStart(2,'0')}}</span></span><i v-if="i<pathSteps.length-1"/></div><article class="step-card"><div class="step-head"><span class="step-tag" :class="step.due?'tag-current':step.wrongCount?'tag-current':'tag-next'">{{step.tag}}</span><span class="step-time"><Clock3 :size="13"/>{{step.time}}</span><span v-if="step.state==='current'" class="now-tag">建议先学</span><span class="path-order-controls"><button type="button" class="path-order-button" :disabled="i===0" :aria-label="`将${step.name}上移`" title="上移" @click="movePathStep(i,-1)"><ChevronUp :size="13"/></button><button type="button" class="path-order-button" :disabled="i===pathSteps.length-1" :aria-label="`将${step.name}下移`" title="下移" @click="movePathStep(i,1)"><ChevronDown :size="13"/></button></span></div><h3>{{step.name}}</h3><p>{{step.reason}}</p><div class="step-mastery"><span>个人掌握度</span><b>{{step.mastery}}%</b></div><div class="progress-line"><i :style="{width:step.mastery+'%'}"/></div><div v-if="step.prerequisites.length" class="step-prereq"><span>前置知识：</span><b>{{step.prerequisites.map(id=>graphNodes.find(node=>node.id===id)?.name||id).join('、')}}</b></div><button v-if="!step.done" class="step-cta" @click="startPathStep(step)">针对该知识点练习 <ArrowRight :size="13"/></button></article></div></div></div><aside class="path-aside"><article class="panel goal-panel"><div class="side-panel-title"><Target :size="16"/><h3>本轮学习目标</h3></div><b class="goal-name">{{pathSteps.find(step=>!step.done)?.name||'巩固已掌握内容'}}</b><p>{{graphCourseName}}</p><div class="goal-ring"><div><strong>{{pathProgress}}%</strong><small>课程掌握</small></div></div><div class="goal-metrics"><span><b>{{pathSteps.length}}</b><small>推荐步骤</small></span><span><b>{{pathSteps.filter(step=>step.due).length}}</b><small>到期复习</small></span><span><b>{{pathSteps.filter(step=>step.wrongCount>0).length}}</b><small>错题关联</small></span></div></article><article class="panel weak-panel"><div class="side-panel-title"><Lightbulb :size="16"/><h3>推荐依据</h3></div><p class="path-reason">优先处理已到期错题和重复错误，再按知识图谱的先修关系补齐前置知识。掌握度达到 80% 的节点会从本轮路线中移除。</p><button class="text-link" @click="router.push({path:'/graph',query:{course:graphCourseId}})">查看课程知识图谱 <ArrowRight :size="13"/></button></article><article class="path-tip"><Sparkles :size="16"/><div><b>个性化排序</b><p>路线读取当前账号掌握度与错题复习状态，并遵循课程知识图谱中的先修关系。</p><small>每次进入或重新规划时更新</small></div></article></aside></section>

    <!-- Quiz -->
    <section v-else-if="section==='quiz'" class="quiz-layout"><aside class="panel quiz-setup"><div class="quiz-setup-icon"><Target :size="20"/></div><h3>测验设置</h3><p>答错后会生成错因提示与间隔复测</p><label>当前课程<select v-model="quizCourseId"><option v-for="course in courses" :key="course.id" :value="course.id">{{course.name}}</option></select></label><label>选择知识点（可选）<select v-model="quizConceptFilter"><option value="">整门课程随机练习</option><option v-for="node in quizConceptOptions" :key="node.id" :value="node.id">{{node.name}}</option></select></label><label>题目数量<select v-model="quizCount"><option value="3">3 题</option><option value="5">5 题</option></select></label><button class="btn btn-primary full-width" @click="beginQuiz"><Sparkles :size="15"/>{{quizStarted&&!quizSubmitted?'重新开始':'开始测验'}}</button><small class="quiz-mock-note"><Info :size="12"/>题库按课程知识点生成；上传资料完成索引后也会补充对应练习</small><small v-if="dueMistakes" class="quiz-mock-note due-note"><Clock3 :size="12"/>有 {{dueMistakes}} 道错题到期复习</small></aside><div class="quiz-main panel"><template v-if="!quizStarted"><div class="quiz-empty"><div class="quiz-illustration"><div><BookOpen :size="26"/></div><span>✦</span><i></i></div><h2>{{dueMistakes?'先复测，再继续新内容':'来一次轻量知识检验'}}</h2><p>答题结果会进入错题本；答错先看错因和知识卡，再用举一反三练习检验是否真正理解。</p><div class="quiz-facts"><span><b>{{quizCount}}</b><small>道练习题</small></span><span><b>次日</b><small>首次复测</small></span><span><b>2 次</b><small>间隔正确后掌握</small></span></div><button class="btn btn-primary" @click="beginQuiz"><Sparkles :size="15"/>开始测验 <ArrowRight :size="14"/></button></div></template><template v-else-if="quizSubmitted"><div class="result-view"><span class="result-eyebrow"><CheckCheck :size="15"/>{{reviewMode?'复测已完成':'测验已完成'}}</span><h2>{{score>=80?'基础掌握得不错！':score>=50?'再巩固一次会更好':'从解析开始稳步提升'}}</h2><p>测验结果已保存到账户，错题复习记录会同步更新。{{reviewMode?'变式题答对后还需间隔复测，才会标记为掌握。':'错误题目已安排次日复测。'}}</p><div class="score-circle" :style="{'--score':score+'%'}"><div><b>{{score}}<small>%</small></b><span>正确率</span></div></div><div class="result-stats"><span><b>{{quizQuestions.filter(x=>x.type!=='简答题').length}}</b><small>客观题</small></span><span><b>{{Math.round(score)}}</b><small>正确率</small></span><span><b>{{dueMistakes}}</b><small>待复习</small></span></div><div class="review-list"><h3>答案解析 · 错因诊断与证据</h3><article v-for="(item,i) in quizQuestions" :key="item.id" class="review-item"><span class="review-mark" :class="{correct:isCorrect(item)}">{{i+1}}</span><div><b>{{item.title}}</b><p v-if="item.type === '简答题'">待人工评阅</p><p v-else>正确答案：{{Array.isArray(item.answer)?item.answer.join('、'):item.answer}}</p><small>{{isCorrect(item)?item.explanation:diagnosisFor(item)}}</small><div v-if="item.evidence" class="quiz-evidence"><strong>{{item.evidence.title}}</strong><span>{{item.evidence.section}} · 内置示例知识卡</span><p>{{item.evidence.excerpt}}</p></div><button v-if="!isCorrect(item)" class="text-link retry-variant" @click="openMistakePractice(item.id)"><RotateCcw :size="13"/>再做三道举一反三练习 <ArrowRight :size="13"/></button></div></article></div><div class="result-actions"><button class="btn btn-secondary" @click="router.push('/mistakes')"><BookOpen :size="14"/>查看错题闭环</button><button class="btn btn-primary" @click="router.push('/analytics')">查看学习记录 <ArrowRight :size="14"/></button></div></div></template><template v-else><div class="quiz-progress-head"><span>{{quizQuestions[0]?.course||quizTopic}} · {{reviewMode?'间隔复测':'知识点自测'}}</span><span>{{reviewMode?'3 道新变式题':'内置示例题'}}</span></div><div class="quiz-progress-track"><i :style="{width:((currentQuestion+1)/quizQuestions.length*100)+'%'}"/></div><div class="question-meta"><span>第 {{currentQuestion+1}} 题 <small>/ {{quizQuestions.length}}</small></span><span class="question-type">{{quizQuestions[currentQuestion]?.type}} · {{quizQuestions[currentQuestion]?.difficulty}}</span></div><h2 class="question-title">{{quizQuestions[currentQuestion]?.title}}</h2><div class="option-list"><button v-for="(option, i) in quizQuestions[currentQuestion]?.options" :key="option" class="quiz-option" :class="{selected: selectedAnswer(quizQuestions[currentQuestion], option)}" @click="toggleAnswer(quizQuestions[currentQuestion], option)"><span class="option-key">{{ ['A','B','C','D'][i] }}</span>{{ option }}<Check v-if="selectedAnswer(quizQuestions[currentQuestion], option)" :size="15" /></button></div>
<textarea v-if="quizQuestions[currentQuestion]?.type === '简答题'" class="short-answer" rows="4" placeholder="写下你的简要回答…" :value="quizAnswers[quizQuestions[currentQuestion].id]" @input="quizAnswers[quizQuestions[currentQuestion].id] = ($event.target as HTMLTextAreaElement).value"></textarea>
<div class="quiz-nav"><button class="btn btn-secondary" :disabled="currentQuestion === 0" @click="currentQuestion--"><ArrowLeft :size="14" />上一题</button><div class="question-dots"><button v-for="(_, i) in quizQuestions" :key="i" :class="{active: i === currentQuestion, answered: quizAnswers[quizQuestions[i].id]}" @click="currentQuestion = i">{{ i + 1 }}</button></div><button v-if="currentQuestion < quizQuestions.length - 1" class="btn btn-primary" @click="currentQuestion++">下一题 <ArrowRight :size="14" /></button><button v-else class="btn btn-primary" @click="submitQuiz"><CheckCheck :size="14" />提交测验</button></div>
<div class="quiz-bottom-note"><Info :size="13" />提交后系统将根据客观题答案计算分数；简答题需要人工评阅。</div></template></div></section>

    <!-- Analytics -->
    <template v-else-if="section==='analytics'"><div class="analytics-controls"><div class="range-toggle"><button class="active" @click="analyticsRange=7" :class="{active:analyticsRange===7}">近 7 天</button><button @click="analyticsRange=30" :class="{active:analyticsRange===30}">近 30 天</button></div><span><Clock3 :size="14"/>统计口径：当前账号的测验与学习记录</span><button class="btn btn-secondary" @click="exportAnalytics"><Download :size="14"/>导出报告</button></div><div class="analytics-stats"><article class="panel"><span>累计测验次数</span><b>{{quizHistory.length}} <small>次</small></b><em>仅统计已提交测验</em></article><article class="panel"><span>完成学习任务</span><b>{{store.tasks.filter(t=>t.done).length}} <small>项</small></b><em>来自账户学习计划</em></article><article class="panel"><span>近 30 天学习时长</span><b>{{studyAnalytics.totalHours}} <small>小时</small></b><em>由开始与结束专注计时累计</em></article><article class="panel"><span>近 {{analyticsRange}} 天平均正确率</span><b>{{averageScore ?? '—'}} <small v-if="averageScore!==null">%</small></b><em>{{rangeRecords.length}} 次测验的平均正确率</em></article></div><div class="analytics-grid"><article class="panel analytics-chart"><div class="panel-heading"><div><h3>每日测验正确率</h3><p>单位：正确率（%）</p></div><span class="chart-period">{{analyticsPeriod}}</span></div><ChartPanel :option="trendOption" height="280px"/></article><article class="panel analytics-chart"><div class="panel-heading"><div><h3>错题复习状态</h3><p>按当前账号错题本掌握状态统计</p></div></div><ChartPanel :option="distributionOption" height="285px"/></article></div><div class="panel weak-table"><div class="panel-heading"><div><h3>需要关注的知识点</h3><p>按未掌握错题次数排序</p></div><button class="text-link" @click="router.push('/mistakes')">进入错题本 <ArrowRight :size="13"/></button></div><div v-for="item in mistakeList" :key="item.id" class="weak-table-row"><span class="weak-indicator"></span><span><b>{{item.topic}}</b><small>{{item.course}} · {{item.wrong}} 次错题</small></span><div class="weak-bar"><i :style="{width:(100-item.wrong*15)+'%'}"/></div><b class="weak-score">{{item.wrong}} 次</b><button class="btn btn-soft" @click="router.push('/mistakes')">去复习 <ArrowRight :size="12"/></button></div></div><div class="analytics-footnote"><Info :size="13"/>测验、错题、学习计划和专注时长均来自当前登录账号。</div></template>

    <!-- Mistakes -->
    <template v-else-if="section==='mistakes'"><div class="mistake-summary"><div class="panel"><span>待复习错题</span><b>{{mistakeList.filter(x=>!x.mastered).length}}</b><small>{{dueMistakes}} 道已到复习时间</small></div><div class="panel"><span>已收藏</span><b>{{mistakeList.filter(x=>x.saved&&!x.mastered).length}}</b><small>优先练习重点题目</small></div><div class="panel"><span>已验证掌握</span><b>{{mistakeList.filter(x=>x.mastered).length}}</b><small>至少两次间隔复测正确</small></div></div><div class="content-toolbar"><select v-model="selectedCourse" class="filter-select"><option>全部课程</option><option v-for="c in courses" :key="c.id">{{c.name}}</option></select><select v-model="mistakeDifficulty" class="filter-select"><option>全部难度</option><option>基础</option><option>中等</option><option>较难</option></select><button class="filter-button" @click="sortMistakesDescending=!sortMistakesDescending"><Filter :size="14"/>{{sortMistakesDescending?'按错误次数排序':'按错误次数升序'}} <ChevronDown :size="13"/></button><span class="toolbar-spacer"></span><button class="btn btn-primary" @click="router.push('/quiz')"><RotateCcw :size="14"/>随机练习</button></div><div class="mistake-list"> <article v-for="item in visibleMistakes" :key="item.id" class="panel mistake-card"><div class="mistake-card-top"><span class="question-type">{{item.course}} · {{item.topic}}</span><span class="difficulty-label">{{item.difficulty}}</span><button class="icon-button" :class="{saved:item.saved}" title="收藏题目" @click="toggleMistakeSaved(item)"><Star :size="17" :fill="item.saved?'currentColor':'none'"/></button></div><h3>{{item.title}}</h3><div class="mistake-detail"><span><RotateCcw :size="13"/>答错 {{item.wrong}} 次</span><span><Clock3 :size="13"/>下次复测：{{new Date(item.nextReviewAt).toLocaleDateString('zh-CN')}}</span><span class="error-rate">已连续答对 {{item.correctStreak}} 次 · {{item.attempts.length}} 条记录</span></div><div class="quiz-evidence mistake-evidence" v-if="item.evidence"><strong>{{item.evidence.title}}</strong><span>{{item.evidence.section}} · 内置示例知识卡</span><p>{{item.evidence.excerpt}}</p></div><p class="mistake-diagnosis"><b>上次错因：</b>{{item.misconception}}</p><div class="mistake-actions"><button class="btn btn-soft" @click="router.push('/graph')"><Network :size="14"/>查看知识图谱</button><button class="btn btn-primary" @click="openMistakePractice(item.questionId)"><RotateCcw :size="14"/>举一反三练习</button></div></article><div v-if="!visibleMistakes.length" class="panel empty-state"><CheckCheck :size="24"/><b>{{mistakeList.length?'当前筛选下没有待复习错题':'完成测验后，答错的题会进入这里'}}</b><span>通过三道新变式题检验理解；至少两次间隔复测正确后标记为掌握。</span><button class="btn btn-primary" @click="router.push('/quiz')">开始一次测验 <ArrowRight :size="14"/></button></div></div></template>

    <!-- Study plan -->
    <template v-else-if="section==='plan'"><div class="plan-toolbar"><div class="plan-date"><button class="icon-button" title="前一天" @click="shiftPlanDate(-1)"><ChevronLeft :size="16"/></button><b>{{planDate}}</b><button class="icon-button" title="后一天" @click="shiftPlanDate(1)"><ChevronRight :size="16"/></button><button class="today-button" @click="goToday">今天</button></div><div><button class="range-toggle active-tab" @click="planView='list'" :class="{active:planView==='list'}">列表</button><button class="range-toggle" @click="planView='calendar'" :class="{active:planView==='calendar'}">日历</button><button class="btn btn-primary" @click="addPlanTask('新增学习任务')"><Plus :size="14"/>新建任务</button></div></div><div class="plan-summary-strip"><span><i></i>待完成 <b>{{store.taskCount}}</b> 项</span><span><CheckCheck :size="14"/>今日完成 <b>{{todayTasks.filter(t=>t.done).length}}</b> 项</span><span><Target :size="14"/>每周目标 <b>{{preferences.weeklyGoalHours}}</b> 小时</span><button @click="addPlanTask('复习本周课程笔记')"><Plus :size="13"/>快速添加</button></div><div v-if="planView==='calendar'" class="panel plan-calendar"><label>选择日期<input v-model="selectedPlanDay" type="date" /></label><button v-for="day in calendarDays" :key="day.value" class="range-toggle" :class="{active:day.value===selectedPlanDay}" @click="selectedPlanDay=day.value">{{day.label}} · {{day.count}} 项</button></div><div v-if="planView==='list'" class="plan-day-group"><div class="day-heading"><span class="day-mark">今</span><div><b>{{selectedPlanDay===new Date().toISOString().slice(0,10)?'今天':'所选日期'}}</b><small>{{planDate}}</small></div><span>{{todayTasks.filter(t=>t.done).length}} / {{todayTasks.length}} 已完成</span></div><article v-for="task in todayTasks" :key="task.id" class="panel plan-task"><button class="task-check" :class="{checked:task.done}" @click="togglePlanTask(task.id)"><Check v-if="task.done" :size="13"/></button><div class="plan-task-main"><b :class="{strike:task.done}">{{task.title}}</b><span><BookOpen :size="12"/>{{task.course}} <i></i><Clock3 :size="12"/>{{task.date.split('·')[1]||'09:00'}}</span></div><span class="priority-tag" :class="task.priority==='高'?'priority-high':task.priority==='中'?'priority-medium':'priority-low'">{{task.priority}}优先级</span><button class="icon-button" @click="editTask(task)"><MoreHorizontal :size="16"/></button></article><button class="add-inline-task" @click="addPlanTask('完成今日学习复盘')"><Plus :size="14"/>添加一个任务</button></div><div v-if="planView==='list'" class="plan-day-group tomorrow"><div class="day-heading"><span class="day-mark">明</span><div><b>下一天</b><small>{{new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'short'}).format(new Date(`${nextPlanDay}T12:00:00`))}}</small></div><span>{{nextDayTasks.length}} 项任务</span></div><article v-for="task in nextDayTasks" :key="task.id" class="panel plan-task"><button class="task-check" :class="{checked:task.done}" @click="togglePlanTask(task.id)"><Check v-if="task.done" :size="13"/></button><div class="plan-task-main"><b :class="{strike:task.done}">{{task.title}}</b><span><BookOpen :size="12"/>{{task.course}} <i></i><Clock3 :size="12"/>10:00</span></div><span class="priority-tag priority-low">{{task.priority}}优先级</span><button class="icon-button" @click="editTask(task)"><MoreHorizontal :size="16"/></button></article><div v-if="nextDayTasks.length===0" class="panel empty-tomorrow">明天还没有安排，给自己留一点自主学习时间也不错。</div></div><div class="plan-local-note"><Info :size="13"/>计划数据已保存到账户。</div></template>

    <!-- Settings -->
    <section v-else-if="section==='settings'" class="settings-layout"><aside class="panel settings-menu"><button class="active" @click="scrollSettings('settings-profile')"><Settings2 :size="15"/>个人资料</button><button @click="scrollSettings('settings-goals')"><Target :size="15"/>学习目标</button><button @click="scrollSettings('settings-goals')"><BellIcon/><span>通知偏好</span></button><button @click="scrollSettings('settings-privacy')"><Info :size="15"/>隐私与数据</button></aside><div class="settings-main"><article id="settings-profile" class="panel settings-card"><div class="settings-heading"><div><h3>个人资料</h3><p>管理你的学习身份与偏好信息。</p></div><button class="btn btn-secondary" @click="saveProfileChanges">保存更改</button></div><div class="profile-edit"><div class="avatar avatar-large">{{ profileDraft.name.slice(0, 1) || '学' }}</div><div><b>个人头像</b><small>当前使用姓名首字，头像上传暂未接入。</small></div></div><div class="form-grid"><label>姓名<input v-model="profileDraft.name" autocomplete="name"/></label><label>学校<input v-model="profileDraft.school" autocomplete="organization"/></label><label>学段<select v-model="profileDraft.educationStage"><option>小学</option><option>初中</option><option>高中</option><option>大学</option><option>其他</option></select></label><label>年级<input v-model="profileDraft.grade" placeholder="例如：四年级、高二、大三"/></label><label>学习学科<input v-model="learningSubjectsText" placeholder="多个学科用顿号分隔"/></label><label>专业<input v-model="profileDraft.major"/></label><label class="span-two">学习目标<input v-model="profileDraft.learningGoal" maxlength="500" placeholder="例如：掌握数据结构基础，准备期末考试"/></label><label class="span-two">个人介绍<textarea v-model="profileDraft.bio" rows="3" placeholder="写一句关于你的学习目标…"></textarea></label></div></article><article id="settings-goals" class="panel settings-card"><div class="settings-heading"><div><h3>学习目标</h3><p>让智学研途依据你的目标安排节奏。</p></div></div><div class="goal-setting-row"><div><b>每周学习目标</b><small>每周希望投入的学习时长</small></div><div class="stepper"><button @click="goal=Math.max(1,goal-1)">−</button><b>{{goal}} 小时</b><button @click="goal++">+</button></div></div><div class="goal-setting-row"><div><b>每日专注时长</b><small>每日学习计划的默认时长</small></div><div class="stepper"><button @click="daily=Math.max(1,daily-1)">−</button><b>{{daily}} 小时</b><button @click="daily++">+</button></div></div><div class="goal-setting-row"><div><b>学习提醒</b><small>接收每日学习计划提醒</small></div><button class="switch-control" :class="{on:notifications}" role="switch" :aria-checked="notifications" @click="notifications=!notifications"><i/></button></div></article><article id="settings-appearance" class="panel settings-card appearance-card"><div><h3>外观与显示</h3><p>选择适合你的学习界面。</p></div><div class="theme-options"><button :class="{selected:!store.dark}" @click="store.dark&&store.toggleTheme()"><span class="theme-preview light-preview"><i/><i/><i/></span><b>浅色模式</b><Check v-if="!store.dark" :size="15"/></button><button :class="{selected:store.dark}" @click="!store.dark&&store.toggleTheme()"><span class="theme-preview dark-preview"><i/><i/><i/></span><b>深色模式</b><Check v-if="store.dark" :size="15"/></button></div></article><article id="settings-privacy" class="panel settings-card"><h3>隐私与数据</h3><p>个人资料、偏好、计划、测验历史和错题均保存在当前账号中。</p></article><div class="settings-local"><Info :size="14"/>课程目录、图谱与题目由服务端数据库提供。</div></div></section>
    <div v-else class="panel empty-state"><CircleHelp :size="24"/><b>页面准备中</b><span>请从左侧导航进入学习空间模块。</span></div>

    <Transition name="fade"><div v-if="sourceSelected" class="overlay" @click.self="sourceSelected=null"><aside class="source-drawer"><div class="drawer-top"><div><small>资料来源 · 本地模拟内容</small><h3>{{sourceSelected.document}}</h3></div><button class="icon-button" @click="sourceSelected=null"><X :size="17"/></button></div><div class="source-meta"><span><BookOpen :size="13"/>{{sourceSelected.section}}</span><span><Sparkles :size="13"/>{{sourceSelected.score}}</span></div><div class="source-preview"><div class="preview-page-label">课程资料片段</div><p>…{{sourceSelected.excerpt}}…</p><div class="highlighted-excerpt">{{sourceSelected.excerpt}}</div><p>以上片段来自当前版本的本地演示内容，用于展示来源定位交互，不代表实际文档检索结果。</p></div><button class="btn btn-primary full-width" @click="sourceSelected=null;router.push('/library')">在资料库中查看 <ArrowUpRight :size="14"/></button></aside></div></Transition>
    <Transition name="toast"><div v-if="toast" class="toast-message"><Check :size="15"/>{{toast}}</div></Transition>
  </div>
</template>




